sys_script_include.script:
var createcmdb = Class.create();
createcmdb.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {


createtable : function(){
	try{

gs.info("CREATE ASSET STARTED");
	gs.sleep(2000);
	var syss =this.getParameter("sysof");



	var current = new GlideRecord("x_snc_it_asset_man_asset_request");
	current.addQuery("sys_id","STARTSWITH",syss);
	current.query();
	gs.info("CREATE ASSET ROW COUNT: "+current.getRowCount());
	if(current.next()){

	var assetType=current.getDisplayValue("type_of_asset");
	var firstTable='';


	var gr = new GlideRecord('sys_db_object');
	gr.addQuery('label',assetType);
	gr.addQuery('name','STARTSWITH','cmdb_ci_');
	gr.setLimit(1);
	gr.query();
	if(gr.next()){
		firstTable=gr.name;
	}

	var grCmdb= new GlideRecord(firstTable);
	grCmdb.initialize();
	grCmdb.manufacturer=current.requestor.company;
	grCmdb.department=current.requestor.department;
	grCmdb.assigned_to=current.requestor;
	var db = grCmdb.insert();
	current.asset = db;


	var grAlmHardware= new GlideRecord('alm_hardware');
	grAlmHardware.initialize();
	grAlmHardware.manufacturer=current.requestor.company;
	grAlmHardware.department=current.requestor.department;
	grAlmHardware.assigned_to=current.requestor;
	grAlmHardware.ci=db;
	grAlmHardware.install_status='2';
	var hardware=grAlmHardware.insert();


	var grCmdbModel = new GlideRecord('cmdb_model');
	grCmdbModel.initialize();
	grCmdbModel.manufacturer=current.requestor.company;
	grCmdbModel.cmdb_model_category='218323293743100044e0bfc8bcbe5d61';
	grCmdbModel.name=current.consumables.getDisplayValue();

	var model = grCmdbModel.insert();


	var grConsumables= new GlideRecord('alm_consumable');
	grConsumables.initialize();
	grConsumables.model=model;
	grConsumables.model_category='218323293743100044e0bfc8bcbe5d61';
	grConsumables.parent=hardware;
	grConsumables.assigned_to=current.requestor;
	grConsumables.location=current.requestor.location;
	grConsumables.install_status='2';

	grConsumables.insert();

	current.update();

		}

		gs.info("CREATE ASSET Completed: "+current.asset +" : "+hardware+ " : "+model);

	return "true";

	}
	catch(ex){
		gs.info("CREATE ASSET ERROR OCCURED: "+ex.message);
	}



},

